package au.edu.sydney.a2t0303;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class AppTest {

    @Test
    void appHasAGreeting() {
        App app = new App();
        assertNotNull(app.getGreeting(), "app should have a greeting");
    }

    @Test
    void greetingIsNotBlank() {
        App app = new App();
        String greeting = app.getGreeting();

        assertNotNull(greeting);
        assertFalse(greeting.isBlank(), "greeting should not be blank");
    }
}
